        List<List<Integer>> result = new ArrayList<>();
        if (nums.length == 0) {
            result.add(new ArrayList<>());
            return result;
        }

        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int num = nums[i];
            nums[i] = nums[0];
            nums[0] = num;
            List<List<Integer>> permutes = permute(Arrays.copyOfRange(nums, 1, n));
            for (List<Integer> permute : permutes) {
                permute.add(0, num);
            }
            result.addAll(permutes);
        }

        return result;
    }

