public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    String inverseStr = "";
    for (String str : strings) {
        int length = str.length();
        if (length > maxLength) {
            maxLength = length;
            inverseStr = str;
        }
    }

    for (String str : strings) {
        if (str.indexOf(inverseStr) != -1) {
            maxLength = Math.max(maxLength, str.length());
            break;
        }
    }
    return maxLength;
}

public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (String string : strings) {
        maxLength = Math.max(maxLength, Math.max(string.length(), string.length() - string.replace(" ", "").length()));
        for (String otherString : strings) {
            if (!string.equals(otherString) && (string.contains(otherString) || otherString.contains(string))) {
                maxLength = Math.max(maxLength, Math.max(string.length(), otherString.length()));
                break;
            }
        }
    }
    return maxLength;
}

public int findLargestSubstring(List<String> strings) {
    // Find the length of the longest string
    int longest = 0;
    for (String str : strings) {
        longest = Math.max(longest, str.length());
    }

    // Iterate through the strings and find the largest substring
    Set<String> substrings = new HashSet<>();
    for (String str : strings) {
        // Check if the string is already in the set of substrings
        if (substrings.contains(str)) {
            continue;
        }

        int start = str.indexOf(str);
        int end = start + str.length();
        // Find the longest substring in the remaining strings
        for (String otherStr : strings) {
            int otherStart = otherStr.indexOf(str);
            if (otherStart != -1) {
                int otherEnd = otherStart + str.length();
                if (otherEnd > end) {
                    end = otherEnd;
                }
            }
        }

        // Add the substring to the set
        substrings.add(str.substring(start, end));
    }

    // Return the size of the largest substring
    return substrings.stream().mapToInt(String::length).max().getAsInt();
}

