public static String convertDatesToWeekdays(String date) {
    // Create a SimpleDateFormat object with the specified date format
    SimpleDateFormat formatter = new SimpleDateFormat("MM dd yyyy");

    // Parse the input date string to a Date object
    Date inputDate = formatter.parse(date);

    // Create a Calendar object from the input date
    Calendar calendar = Calendar.getInstance();
    calendar.setTime(inputDate);

    // Get the weekday of the input date
    int weekday = calendar.get(Calendar.DAY_OF_WEEK);

    // Return the weekday name
    switch (weekday) {
        case Calendar.SUNDAY:
            return "Sunday";
        case Calendar.MONDAY:
            return "Monday";
        case Calendar.TUESDAY:
            return "Tuesday";
        case Calendar.WEDNESDAY:
            return "Wednesday";
        case Calendar.THURSDAY:
            return "Thursday";
        case Calendar.FRIDAY:
            return "Friday";
        case Calendar.SATURDAY:
            return "Saturday";
        default:
            return null;
    }
}

public static String convertDatesToWeekdays(String date) {
    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);
    Calendar calendar = Calendar.getInstance();
    calendar.set(year, month - 1, day);
    int dayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);
    String weekday = "";
    switch (dayOfWeek) {
        case Calendar.SUNDAY:
            weekday = "Sunday";
            break;
        case Calendar.MONDAY:
            weekday = "Monday";
            break;
        case Calendar.TUESDAY:
            weekday = "Tuesday";
            break;
        case Calendar.WEDNESDAY:
            weekday = "Wednesday";
            break;
        case Calendar.THURSDAY:
            weekday = "Thursday";
            break;
        case Calendar.FRIDAY:
            weekday = "Friday";
            break;
        case Calendar.SATURDAY:
            weekday = "Saturday";
            break;
    }
    return month + " " + day + ", " + year + " is a " + weekday;
}

