        Arrays.sort(arr);
        int n = arr.length / 20;
        double sum = 0;
        for (int i = n; i < arr.length - n; i++) {
            sum += arr[i];
        }
        return sum / (arr.length - 2 * n);
    }

public double trimMean(int[] arr) {
    int len = arr.length;
    double sum = 0;

    // calculate the sum of all elements in the array
    for (int i = 0; i < len; i++) {
        sum += arr[i];
    }

    // calculate the mean of the elements
    double mean = sum / len;

    // calculate the trimmed mean
    double trimMean = 0;
    for (int i = 0; i < len; i++) {
        if (arr[i] > mean - 0.05 * mean && arr[i] < mean + 0.05 * mean) {
            trimMean += arr[i];
        }
    }
    trimMean /= (len - 2);

    return trimMean;
}

public static double trimMean(int[] arr) {
    if (arr.length == 0) {
        return 0.0;
    }

    // Calculate the 5% trim
    int trim = (int) (arr.length * 0.05);

    // Sort the array in ascending order
    Arrays.sort(arr);

    // Remove the smallest and largest 5% of the elements
    int[] trimmed = Arrays.copyOfRange(arr, trim, arr.length - trim);

    // Calculate the mean of the remaining elements
    return IntStream.of(trimmed).average().orElse(0.0);
}

