    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1], true);
    }

    // Initialize the visited and hasApple arrays
    boolean[] visited = new boolean[n];
    boolean[] hasApple = new boolean[n];

    // Initialize the minTime variable
    int minTime = Integer.MAX_VALUE;

    // Depth-first search to find the minimum time
    minTime(graph, visited, hasApple, 0, 0, minTime);

    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    //initialize a distance array to keep track of the minimum distance from each node to node 0
    int[] distance = new int[n];
    for (int i = 0; i < n; i++) {
        distance[i] = Integer.MAX_VALUE;
    }
    distance[0] = 0;

    //initialize a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);

    //perform BFS to find the minimum distance from each node to node 0
    while (!queue.isEmpty()) {
        int curr = queue.remove();
        for (int neighbor : neighbors(curr, edges)) {
            if (distance[neighbor] == Integer.MAX_VALUE) {
                distance[neighbor] = distance[curr] + 1;
                queue.add(neighbor);
            }
        }
    }

    //initialize the minimum time required to collect all the apples and return to node 0
    int minTime = 0;

    //iterate through all the nodes
    for (int i = 0; i < n; i++) {
        //if the current node has an apple, add the distance from this node to node 0 to the minimum time
        if (hasApple[i]) {
            minTime += distance[i];
        }
    }

    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the disjoint set forest
    DisjointSetForest forest = new DisjointSetForest(n);

    // Add the edges to the disjoint set forest
    for (int[] edge : edges) {
        int root1 = forest.find(edge[0]);
        int root2 = forest.find(edge[1]);
        forest.union(root1, root2);
    }

    // Initialize the minimum time to 0
    int minTime = 0;

    // Iterate over the nodes in the disjoint set forest
    for (int node = 0; node < n; node++) {
        // If the node has an apple, add the time required to collect it
        if (hasApple[node]) {
            minTime += forest.size(node);
        }

        // Update the minimum time
        minTime = Math.min(minTime, forest.getMinTime(node));
    }

    return minTime;
}

public String sortString(String s) {
    if (s.isEmpty()) {
        return "";
    }
    StringBuilder result = new StringBuilder();
    Set<Character> unusedChars = new HashSet<>();
    for (char c : s.toCharArray()) {
        unusedChars.add(c);
    }
    while (!unusedChars.isEmpty()) {
        char smallest = (char) Integer.MAX_VALUE;
        char largest = (char) Integer.MIN_VALUE;
        for (char c : unusedChars) {
            smallest = (char) Math.min(smallest, c);
            largest = (char) Math.max(largest, c);
        }
        result.append(smallest);
        unusedChars.remove(smallest);
        if (smallest != largest) {
            result.append(largest);
            unusedChars.remove(largest);
        }
    }
    return result.toString();
}

public static String sortString(String s) {
    // Step 1: Find the smallest character and append it to the result.
    StringBuilder result = new StringBuilder();
    int currentIndex = 0;
    char currentChar = s.charAt(0);
    result.append(currentChar);
    // Step 2: Pick the smallest character which is greater than the last appended character
    while(currentChar < 'z') {
        currentIndex = s.indexOf(++currentChar, currentIndex);
        if(currentIndex == -1) break;
        result.append(s.charAt(currentIndex));
    }
    // Step 3: Repeat step 2 until all characters are picked
    while(result.length() < s.length()) {
        currentChar = s.charAt(s.length() - 1);
        currentIndex = s.indexOf(currentChar,currentIndex - 1);
        if(currentIndex == -1) {
          break;
        }
        result.append(s.charAt(currentIndex--));
    }
    return result.toString();
}

public String sortString(String s) {
	// Step 1: Pick the smallest character from s and append it to the result.
	char minChar = s.charAt(0);
	String result = String.valueOf(minChar);

	// Step 2: Pick the smallest character which is greater than the last appended character to the result and append it.
	for (int i = 1; i < s.length(); i++) {
		char currChar = s.charAt(i);
		if (currChar > minChar) {
			result += currChar;
			minChar = currChar;
		}
	}

	// Step 3: Repeat step 2 until you cannot pick more characters.
	while (result.length() < s.length()) {
		for (int i = 0; i < s.length(); i++) {
			char currChar = s.charAt(i);
			if (!result.contains(String.valueOf(currChar))) {
				result += currChar;
			}
		}
	}

	// Step 4: Pick the largest character from s and append it to the result.
	char maxChar = s.charAt(s.length() - 1);
	result += String.valueOf(maxChar);

	// Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it.
	for (int i = s.length() - 2; i >= 0; i--) {
		char currChar = s.charAt(i);
		if (currChar < maxChar) {
			result += currChar;
			maxChar = currChar;
		}
	}

	// Step 6: Repeat step 5 until you cannot pick more characters.
	while (result.length() < s.length()) {
		for (int i = s.length() - 1; i >= 0; i--) {
			char currChar = s.charAt(i);
			if (!result.contains(String.valueOf(currChar))) {
				result += currChar;
			}
		}
	}

	return result;
}

