public boolean splitArraySameAverage(int[] nums) {
    // Calculate the average of the input array
    double average = Arrays.stream(nums).average().getAsDouble();

    // Initialize two arrays to store the numbers of the two subarrays
    List<Integer> subarray1 = new ArrayList<>();
    List<Integer> subarray2 = new ArrayList<>();

    // Iterate through the input array and add each number to either subarray1 or subarray2
    for (int num : nums) {
        if (subarray1.size() == 0 || Math.abs(subarray1.stream().average().getAsDouble() - average) <= Math.abs(subarray2.stream().average().getAsDouble() - average)) {
            subarray1.add(num);
        } else {
            subarray2.add(num);
        }
    }

    // Check if the two subarrays have the same average
    return Math.abs(subarray1.stream().average().getAsDouble() - average) == Math.abs(subarray2.stream().average().getAsDouble() - average);
}

public boolean splitArraySameAverage(int[] nums) {
    double average = (double) Arrays.stream(nums).sum() / nums.length;
    double[] first = new double[nums.length / 2];
    double[] second = new double[nums.length - first.length];
    for (int i = 0; i < nums.length; i++) {
        if (first.length > 0 && first[0] == average) {
            first = Arrays.copyOfRange(nums, i + 1, nums.length);
            second = nums;
        } else if (second.length > 0 && second[0] == average) {
            first = nums;
            second = Arrays.copyOfRange(nums, i + 1, nums.length);
        } else {
            break;
        }
    }
    return Arrays.equals(first, second);
}

public boolean splitArraySameAverage(int[] nums) {
