public static boolean hasAllCodes(String s, int k) {
        Set<String> substrings = new HashSet<String>();
        for (int i = 0; i <= s.length() - k; i++) {
            String substring = s.substring(i, i + k);
            substrings.add(substring);
        }
        return substrings.size() == (int) Math.pow(2, k);
    }

public boolean hasAllCodes(String s, int k) {
    for (int i = 0; i <= s.length() - k; i++) {
        String substr = s.substring(i, i + k);
        for (int j = 0; j < 1 << k; j++) {
            String substr2 = Integer.toBinaryString(j);
            if (substr2.length() < k) {
                substr2 = "0".repeat(k - substr2.length()) + substr2;
            }
            if (!substr.equals(substr2)) {
                return false;
            }
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    // Initialize a set to store all binary strings of length k
    Set<String> binaryStrings = new HashSet<>();
    // Iterate over all possible binary strings of length k
    for (int i = 0; i < (1 << k); i++) {
        // Convert i to a binary string of length k
        String binaryString = String.format("%" + k + "s", Integer.toBinaryString(i)).replace(' ', '0');
        // If s does not contain the binary string, return false
        if (!s.contains(binaryString)) {
            return false;
        }
        // Add the binary string to the set
        binaryStrings.add(binaryString);
    }
    // If all binary strings of length k are found, return true
    return true;
}

