public ModResourceManager() {
        LOGGER.info("Initializing Mod Resource Manager");

        determineSide();
        new ResourcePackManager();
        WaveLoader.init();

        Set<String> loadedMods = loadMods();

        cleanUpResources(loadedMods, new File(ResourcePackManager.getInstance().getPackDir(), "data"));
        cleanUpResources(loadedMods, new File(ResourcePackManager.getInstance().getPackDir(), "assets"));

        WaveShapedRecipe.build(new File(mainFolder, "resource_pack/data"));

        if (Side.isClient()) {
            LangManager.write();
        }
    }

    private void determineSide() {
        try {
            net.minecraft.client.MinecraftClient.getInstance();
            Side.isServer = false;
        } catch (Exception e) {
            Side.isServer = true;
        }
    }

    private Set<String> loadMods() {
        Set<String> loaded = new HashSet<>();
        for (Map.Entry<String, WaveLoader.WrappedWaveMod> mod : WaveLoader.getMods().entrySet()) {
            bake = mod.getValue().changed;
            if (bake) {
                FileUtil.recursivelyDelete(new File(ResourcePackManager.getInstance().getPackDir(), "data/" + mod.getValue().mod.name));
                FileUtil.recursivelyDelete(new File(ResourcePackManager.getInstance().getPackDir(), "assets/" + mod.getValue().mod.name));
            }
            loaded.add(mod.getValue().mod.name);
            mod.getValue().mod.init();
        }
        return loaded;
    }

    public void cleanUpResources(Set<String> loadedMods, File directory) {
        File[] files = directory.listFiles();
        if (files != null) {
            for (File f : files) {
                if (!loadedMods.contains(f.getName())) {
                    FileUtil.recursivelyDelete(f);
                }
            }
        }
    }

