            substring.append(s.charAt(j));
            // If the substring is not already in the set, add it
            if (!uniqueSubstrings.contains(substring.toString())) {
                uniqueSubstrings.add(substring.toString());
                // Increment the counter
                maxUniqueSubstrings++;
            }
        }
    }
    return maxUniqueSubstrings;
}

