public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][][] dp = new int[m][n][4];
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int left = (i > 0) ? dp[i - 1][j][0] : 0;
            int up = (j > 0) ? dp[i][j - 1][1] : 0;
            int leftUp = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] : 0;
            int leftDown = (i < m - 1 && j > 0) ? dp[i + 1][j - 1][3] : 0;

            int curr = 0;
            if (mat[i][j] == 1) {
                curr = Math.max(Math.max(left, up), Math.max(leftUp, leftDown)) + 1;
                maxLength = Math.max(maxLength, curr);
            }

            dp[i][j] = new int[]{curr, curr, curr, curr};
        }
    }

    return maxLength;
}

