public static int[] diagonalOrder(int[][] mat) {
    Queue<Integer> queue = new LinkedList<>();

    // Iterate over the rows of the matrix
    for (int i = 0; i < mat.length; i++) {
        // Iterate over the columns of the row
        for (int j = 0; j < mat[i].length; j++) {
            // Enqueue the element at position (i, j)
            queue.add(mat[i][j]);
        }
    }

    // Create a list to hold the elements in diagonal order
    List<Integer> result = new ArrayList<>();

    // Dequeue the elements from the queue and add them to the list
    while (!queue.isEmpty()) {
        result.add(queue.remove());
    }

    // Return the list as the result
    return result.toArray(new int[result.size()]);
}

public static int[] diagonalOrder(int[][] mat) {
        // Create a list to store the diagonal elements
        List<Integer> diagonal = new ArrayList<>();

        // Loop through each diagonal starting from the main diagonal
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat[i].length; j++) {
                diagonal.add(mat[i][j]);
            }
        }

        // Loop through each diagonal starting from the second diagonal
        for (int i = 1; i < mat.length; i++) {
            for (int j = 0; j < mat[i].length - i; j++) {
                diagonal.add(mat[i][j + i]);
            }
        }

        return diagonal.toArray();
    }

