public static int findSmallestInteger(int n) {
    // Get the digits of the input number as an array
    int[] digits = String.valueOf(n).chars().map(c -> c - '0').toArray();

    // Sort the digits in descending order
    Arrays.sort(digits);

    // Build the new number by concatenating the sorted digits
    int newNumber = 0;
    for (int digit : digits) {
        newNumber = newNumber * 10 + digit;
    }

    // Return the new number if it's greater than the input number, or -1 otherwise
    return newNumber > n ? newNumber : -1;
}

