}

public static int findSmallestInteger(int n) {
    // Convert n to a String so we can manipulate the digits
    String digits = String.valueOf(n);

    // Sort the digits in descending order
    char[] sorted = digits.toCharArray();
    java.util.Arrays.sort(sorted);

    // Check if the sorted digits can be rearranged to form an integer greater than n
    for (int i = 0; i < sorted.length; i++) {
        int newDigit = Integer.parseInt(String.valueOf(sorted[i]));
        if (newDigit > n) {
            return newDigit;
        }
    }

    // If we reach this point, it means we were unable to find a valid rearrangement
    return -1;
}

