public static boolean isBoomerang(int[][] points) {
    for (int i = 0; i < points.length; i++) {
        for (int j = i + 1; j < points.length; j++) {
            int[] p1 = points[i];
            int[] p2 = points[j];
            if (p1[0] != p2[0] && p1[1] != p2[1]) {
                int[] p3 = points[(i + 1) % points.length];
                int[] p4 = points[(j + 1) % points.length];
                if ((p1[0] - p3[0]) * (p2[1] - p4[1]) == (p1[1] - p3[1]) * (p2[0] - p4[0])) {
                    return false;
                }
            }
        }
    }
    return true;
}

public static boolean isBoomerang(int[][] points) {
    // Check that the input is valid
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        return false;
    }

    // Compute the pairwise distances between the points
    int dx1 = points[0][0] - points[1][0];
    int dy1 = points[0][1] - points[1][1];
    int dx2 = points[1][0] - points[2][0];
    int dy2 = points[1][1] - points[2][1];
    int dx3 = points[2][0] - points[0][0];
    int dy3 = points[2][1] - points[0][1];

    // Check that the distance between the first and second points is equal to the sum of the distances from the third point to each of the first two points
    if (Math.sqrt((dx1 * dx1) + (dy1 * dy1)) == Math.sqrt((dx2 * dx2) + (dy2 * dy2)) + Math.sqrt((dx3 * dx3) + (dy3 * dy3))) {
        // Check that the distance between the second and third points is equal to the sum of the distances from the first point to each of the second two points
        if (Math.sqrt((dx2 * dx2) + (dy2 * dy2)) == Math.sqrt((dx3 * dx3) + (dy3 * dy3)) + Math.sqrt((dx1 * dx1) + (dy1 * dy1))) {
            // Check that the distance between the third and first points is equal to the sum of the distances from the second point to each of the first two points
            if (Math.sqrt((dx3 * dx3) + (dy3 * dy3)) == Math.sqrt((dx1 * dx1) + (dy1 * dy1)) + Math.sqrt((dx2 * dx2) + (dy2 * dy2))) {
                return true;
            }
        }
    }

    return false;
}

