public static boolean isBoomerang(int[][] points) {
    // Check if there are exactly 3 points
    if (points.length != 3) {
        return false;
    }

    // Check if the points form a horizontal, vertical, or 45-degree diagonal line
    if (points[0][0] == points[1][0] && points[0][1] == points[2][1]) {
        return false;
    }
    if (points[0][1] == points[1][1] && points[0][0] == points[2][0]) {
        return false;
    }
    if ((points[0][0] - points[1][0]) * (points[0][0] - points[2][0]) == 0 &&
            (points[0][1] - points[1][1]) * (points[0][1] - points[2][1]) == 0) {
        return false;
    }

    // Check if the triangular inequality is satisfied
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                if (i != j && i != k && j != k) {
                    if (points[i][0] == points[j][0] && points[j][0] == points[k][0] && points[i][1] == points[j][1] && points[j][1] == points[k][1]) {
                        return false;
                    }
                }
            }
        }
    }

    return true;
}

