public static int findNthUglyNumber(int n) {
	if (n <= 0) {
		throw new IllegalArgumentException("n should be greater than 0");
	}

	int[] data = new int[n];
	data[0] = 1;

	int x = 0;
	int y = 0;
	int z = 0;

	for (int i = 1; i < n; i++) {
		data[i] = Math.min(x, Math.min(y, z));

		if (data[i] == x) {
			x+=2;
		}
		if (data[i] == y) {
			y+=2;
		}
		if (data[i] == z) {
			z+=2;
		}
	}
	return data[n-1];
}

public static int findNthUglyNumber(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n == 1) {
            return 1;
        }
        int i = 2;
        int[] uglys = new int[n];
        uglys[0] = 1;
        int index = 1;
        while (index < n) {
            int j = i * 2;
            if (j >= n) {
                break;
            }
            int k = i * 3;
            if (k >= n) {
                break;
            }
            int l = i * 5;
            if (l >= n) {
                break;
            }
            if (uglys[j - 1] == 0) {
                uglys[j - 1] = 1;
                index++;
            }
            if (uglys[k - 1] == 0) {
                uglys[k - 1] = 1;
                index++;
            }
            if (uglys[l - 1] == 0) {
                uglys[l - 1] = 1;
                index++;
            }
            i++;
        }
        return uglys[n - 1];
    }

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[]{};
    int temp = 0;

    for (int i = 1; i <= n; i++) {
        if (temp % 2 == 0 && !contains(uglyNumbers, temp * 2)) {
            uglyNumbers[i] = temp * 2;
        } else if (temp % 3 == 0 && !contains(uglyNumbers, temp * 3)) {
            uglyNumbers[i] = temp * 3;
        } else if (temp % 5 == 0 && !contains(uglyNumbers, temp * 5)) {
            uglyNumbers[i] = temp * 5;
        } else {
            uglyNumbers[i] = temp;
        }
        temp++;
    }

    return uglyNumbers[n];
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    int nextUglyNumber = 1;
    int p2 = 0, p3 = 0, p5 = 0;

    uglyNumbers[0] = 1;

    for (int i = 1; i < n; i++) {
        nextUglyNumber = Math.min(uglyNumbers[p2] * 2, Math.min(uglyNumbers[p3] * 3, uglyNumbers[p5] * 5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == uglyNumbers[p2] * 2) p2++;
        if (nextUglyNumber == uglyNumbers[p3] * 3) p3++;
        if (nextUglyNumber == uglyNumbers[p5] * 5) p5++;
    }

    return nextUglyNumber;
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int currentEnergy = 1;
    char previousChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar == previousChar) {
            currentEnergy++;
        } else {
            energy = Math.max(energy, currentEnergy);
            currentEnergy = 1;
        }
        previousChar = currentChar;
    }
    energy = Math.max(energy, currentEnergy);
    return energy;
}

