    int count = 0;
    char currentChar = '\0';

    for (char c : s.toCharArray()) {
        if (currentChar == '\0') {
            currentChar = c;
            count++;
        } else if (c == currentChar) {
            count++;
        } else {
            if (count > energy) {
                energy = count;
            }
            currentChar = c;
            count = 1;
        }
    }
    return energy;
