public static int minPerfectSquareSum(int n) {
        // Initialize a list to store the perfect square numbers
        List<Integer> perfectSquares = new ArrayList<>();
        // Iterate from 1 to sqrt(n)
        for (int i = 1; i <= (int) Math.sqrt(n); i++) {
            // Check if i is a perfect square
            if (i * i == n) {
        // If it is, add it to the list and return 1
                perfectSquares.add(i);
                return 1;
            } else {
        // If it's not, add it to the list and increment the count
                perfectSquares.add(i);
            }
        }
        // If no perfect square is found, return -1
        return -1;
    }

