    return count;
}

public static int minPerfectSquareSum(int n) {
    int minCount = Integer.MAX_VALUE;
    for (int i = 1; i * i <= n; i++) {
        int count = minPerfectSquareSum(n - i * i);
        if (count != -1) {
            minCount = Math.min(minCount, count);
        }
    }
    return minCount != Integer.MAX_VALUE ? minCount + 1 : -1;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        count++;
        n -= root * root;
    }

    return count;
}

